<template>
  <div class="space-y-6">
    <PageHeader title="策略模拟" parent="分流" description="使用真实策略草稿和共享匹配逻辑测试；节点运行状态由配置发布决定。" />
    <ErrorState v-if="error" :message="error" @retry="load" />
    <div class="grid lg:grid-cols-2 gap-6">
      <form @submit.prevent="simulate" class="panel-card p-6 space-y-4">
        <h2 class="font-semibold">请求条件</h2>
        <label class="block text-sm">入口节点<select v-model="form.nodeId" required @change="form.inboundId = ''" class="form-input-base mt-2"><option value="">请选择</option><option v-for="node in nodes" :key="node.id" :value="node.id">{{ node.name }}</option></select></label>
        <label class="block text-sm">入站（可选，用于默认出站）<select v-model="form.inboundId" class="form-input-base mt-2"><option value="">默认 Direct</option><option v-for="inbound in inbounds.filter(item => item.nodeId === form.nodeId)" :key="inbound.id" :value="inbound.id">{{ inbound.name }} · {{ inbound.protocol }}</option></select></label>
        <div class="grid sm:grid-cols-2 gap-4"><label class="text-sm">用户<select v-model="form.userId" @change="form.deviceId = ''" class="form-input-base mt-2"><option value="">未指定</option><option v-for="user in users" :key="user.id" :value="user.id">{{ user.username }}</option></select></label><label class="text-sm">设备<select v-model="form.deviceId" class="form-input-base mt-2"><option value="">未指定</option><option v-for="device in devices.filter(item => !form.userId || item.userId === form.userId)" :key="device.id" :value="device.id">{{ device.name }}</option></select></label></div>
        <label class="block text-sm">域名<input v-model="form.domain" placeholder="api.example.com，不包含 URL 路径" class="form-input-base mt-2" /></label><label class="block text-sm">目标 IP（可选）<input v-model="form.targetIp" placeholder="192.0.2.10" class="form-input-base mt-2" /></label>
        <div class="grid sm:grid-cols-2 gap-4"><label class="text-sm">端口<input v-model.number="form.port" type="number" min="1" max="65535" required class="form-input-base mt-2" /></label><label class="text-sm">网络<select v-model="form.network" class="form-input-base mt-2"><option value="tcp">TCP</option><option value="udp">UDP</option></select></label></div>
        <label class="block text-sm">请求时间（{{ authState.timezone }}；空白使用当前时间）<input v-model="timeLocal" type="datetime-local" class="form-input-base mt-2" /></label>
        <p v-if="simulationError" role="alert" class="text-sm text-red-600">{{ simulationError }}</p><button :disabled="busy" class="ios-btn-primary w-full justify-center disabled:opacity-40">{{ busy ? '模拟中…' : '模拟策略草稿' }}</button>
      </form>
      <section class="panel-card p-6">
        <h2 class="font-semibold mb-4">匹配结果</h2><p v-if="!decision" class="text-sm text-gray-500">提交请求条件后，展示命中规则、动作和配置路径。</p>
        <template v-else><div class="p-4 rounded-xl mb-5" :class="decision.action.type === 'Block' ? 'bg-red-50 text-red-700' : 'bg-blue-50 text-blue-800'"><h3 class="font-semibold">{{ decision.matched ? decision.policyName || decision.policyId : '入站默认规则' }}</h3><p class="text-sm mt-2">{{ actionNames[decision.action.type] }}{{ decision.matched ? ' · 优先级 ' + decision.priority : '' }}</p></div>
          <dl class="space-y-5 text-sm"><div><dt class="text-gray-500">匹配说明</dt><dd class="mt-1">{{ decision.matched ? '已匹配生效范围、地址、端口、网络和时间窗口。' : '未命中启用策略，使用入站默认出站。' }}</dd></div><div><dt class="text-gray-500">配置路径</dt><dd class="mt-1 break-all">{{ decision.path?.map(id => nodes.find(node => node.id === id)?.name || id).join(' → ') || '—' }}</dd></div><div v-if="decision.candidatePaths?.length"><dt class="text-gray-500">候选出口路径 · {{ strategyNames[decision.selectionStrategy || ''] || decision.selectionStrategy }}</dt><dd v-for="(path, index) in decision.candidatePaths" :key="index" class="mt-2">{{ path.map(id => nodes.find(node => node.id === id)?.name || id).join(' → ') }}</dd><p class="text-xs text-gray-500 mt-2">实际选择由节点健康结果与连接调度决定。</p></div><div><dt class="text-gray-500">出站协议</dt><dd>{{ decision.outboundProtocol || '—' }}</dd></div><div><dt class="text-gray-500">最终配置出口</dt><dd>{{ nodes.find(node => node.id === decision.finalEgressNodeId)?.name || decision.finalEgressNodeId || (decision.action.type === 'OutboundGroup' ? '由节点调度选择' : '阻断') }}</dd></div><div><dt class="text-gray-500">失败策略</dt><dd>{{ decision.action.failover || 'Block' }}</dd></div><div><dt class="text-gray-500">记录设置</dt><dd>{{ decision.logging?.log_domain ? '域名记录开启' : '域名记录关闭或默认' }} · {{ decision.logging?.log_traffic ? '流量记录开启' : '流量记录关闭或默认' }}</dd></div></dl><p class="text-xs text-gray-500 mt-6">路径来自策略草稿和配置拓扑，不是实时连通性探测。服务规则修改需要发布后才在节点生效。</p>
        </template>
      </section>
    </div>
  </div>
</template>
<script setup lang="ts">
import { ref, reactive, onMounted } from 'vue'; import { useRoute } from 'vue-router'; import { policyAPI, actionNames, type Decision } from '../api'; import { request, type Page } from '../../../app/apiClient'; import { authState } from '../../../app/auth'; import { utcInput } from '../../../app/time'; import { userAPI, type ProxyUser, type ProxyDevice } from '../../users/api'; import { type NodeView } from '../../nodes/api'; import { proxyAPI, type Inbound, strategyNames } from '../../proxy/api'; import PageHeader from '../../../components/PageHeader.vue'; import ErrorState from '../../../components/ErrorState.vue';
const route = useRoute(); const form = reactive({ nodeId: '', inboundId: '', userId: '', deviceId: '', domain: typeof route.query.domain === 'string' ? route.query.domain : '', targetIp: '', port: 443, network: 'tcp' }); const timeLocal = ref(''); const nodes = ref<NodeView[]>([]); const users = ref<ProxyUser[]>([]); const devices = ref<ProxyDevice[]>([]); const inbounds = ref<Inbound[]>([]); const error = ref(''); const simulationError = ref(''); const busy = ref(false); const decision = ref<Decision | null>(null);
async function load() { try { const [n, u, d, i] = await Promise.all([request<Page<NodeView>>('/nodes?page=1&pageSize=100'), userAPI.list(1, '', 100), userAPI.devices('', 1, 100), proxyAPI.inbounds('', 1, 100)]); nodes.value = n.items; users.value = u.items; devices.value = d.items; inbounds.value = i.items; error.value = ''; } catch (e) { error.value = (e as Error).message; } }
async function simulate() { if (busy.value) return; busy.value = true; simulationError.value = ''; decision.value = null; try { decision.value = await policyAPI.simulate({ ...form, time: timeLocal.value ? utcInput(timeLocal.value) : undefined }); } catch (e) { simulationError.value = (e as Error).message; } finally { busy.value = false; } } onMounted(load);
</script>

